@@ -0,0 +1,237 @@
+//! Prepared command publication cohorts: caller threads elect one publisher.
+//! No worker/cache; queue lifetimes retain existing prepared snapshot leases.
+//! server.rs owns authority acquisition, validation, WAL flush and replies.
+use std::collections::VecDeque;
+use std::io;
+use std::sync::{Arc, Mutex};
+use std::sync::atomic::{AtomicBool, Ordering};
+use std::thread::{self, Thread};
+use std::time::Instant;
+use crate::authority::{AuthorityTransaction, AuthorityCommitResult};
+use crate::wal::WalWitness;
+
+pub(crate) type Published = io::Result<(AuthorityCommitResult, Option<WalWitness>)>;
+pub(crate) struct Pending {
+    transaction: Mutex<Option<AuthorityTransaction>>,
+    result: Mutex<Option<Published>>,
+    thread: Thread,
+    deadline: Instant,
+    deadline_unix_ms: u64,
+    completed: AtomicBool,
+    authorization_requested: AtomicBool,
+    authorized: AtomicBool,
+    publisher: Mutex<Option<Thread>>,
+    cancelled: AtomicBool,
+}
+impl Pending {
+    pub(crate) fn authorization_requested(&self) -> bool {
+        self.authorization_requested.load(Ordering::Acquire) && !self.authorized.load(Ordering::Acquire)
+    }
+    pub(crate) fn request_authorization(&self) {
+        *self.publisher.lock().unwrap_or_else(|e| e.into_inner()) = Some(thread::current());
+        self.authorization_requested.store(true, Ordering::Release);
+        self.thread.unpark();
+    }
+    pub(crate) fn authorize(&self) {
+        self.authorized.store(true, Ordering::Release);
+        if let Some(publisher) = self.publisher.lock().unwrap_or_else(|e| e.into_inner()).as_ref() { publisher.unpark(); }
+    }
+    pub(crate) fn wait_for_authorization(&self) {
+        while !self.authorized.load(Ordering::Acquire) && !self.cancelled.load(Ordering::Acquire) {
+            let remaining = self.deadline.saturating_duration_since(Instant::now());
+            if remaining.is_zero() { break; }
+            thread::park_timeout(remaining.min(std::time::Duration::from_millis(25)));
+        }
+    }
+    pub(crate) fn take_transaction(&self, now_unix_ms: u64) -> io::Result<Option<AuthorityTransaction>> {
+        if self.cancelled.load(Ordering::Acquire) { return Ok(None); }
+        if Instant::now() >= self.deadline || now_unix_ms >= self.deadline_unix_ms {
+            return Err(io::Error::new(io::ErrorKind::TimedOut, "publication deadline elapsed"));
+        }
+        if !self.authorized.load(Ordering::Acquire) {
+            return Err(io::Error::other("publication member lacks caller approval"));
+        }
+        let mut transaction = self.transaction.lock().map_err(|_| io::Error::other("publication transaction poisoned"))?;
+        if self.cancelled.load(Ordering::Acquire) { return Ok(None); }
+        Ok(transaction.take())
+    }
+    pub(crate) fn reply(&self, result: Published) {
+        if self.completed.swap(true, Ordering::AcqRel) { return; }
+        *self.result.lock().unwrap_or_else(|e| e.into_inner()) = Some(result);
+        self.thread.unpark();
+    }
+    pub(crate) fn take_result(&self) -> Option<Published> {
+        self.result.lock().unwrap_or_else(|e| e.into_inner()).take()
+    }
+}
+#[derive(Default)]
+pub(crate) struct PublicationQueue {
+    waiting: Mutex<VecDeque<Arc<Pending>>>,
+    publishing: AtomicBool,
+}
+pub(crate) struct Leadership<'a>(&'a PublicationQueue);
+impl Drop for Leadership<'_> {
+    fn drop(&mut self) {
+        let waiting = self.0.waiting.lock().unwrap_or_else(|e| e.into_inner());
+        self.0.publishing.store(false, Ordering::Release);
+        if let Some(next) = waiting.front() { next.thread.unpark(); }
+    }
+}
+impl PublicationQueue {
+    pub(crate) fn enqueue(&self, transaction: AuthorityTransaction, deadline: Instant, deadline_unix_ms: u64) -> Arc<Pending> {
+        let pending = Arc::new(Pending { transaction: Mutex::new(Some(transaction)),
+            result: Mutex::new(None), thread: thread::current(), deadline, deadline_unix_ms, completed: AtomicBool::new(false),
+            authorization_requested: AtomicBool::new(false), authorized: AtomicBool::new(false), publisher: Mutex::new(None),
+            cancelled: AtomicBool::new(false) });
+        self.waiting.lock().unwrap_or_else(|e| e.into_inner()).push_back(Arc::clone(&pending));
+        pending
+    }
+    pub(crate) fn try_lead(&self, pending: &Arc<Pending>) -> Option<Leadership<'_>> {
+        let waiting = self.waiting.lock().unwrap_or_else(|e| e.into_inner());
+        if !waiting.front().is_some_and(|next| Arc::ptr_eq(next, pending)) { return None; }
+        self.publishing.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
+            .ok().map(|_| Leadership(self))
+    }
+    #[cfg(test)]
+    pub(crate) fn pending_count(&self) -> usize { self.waiting.lock().unwrap().len() }
+
+    pub(crate) fn take_batch(&self) -> Cohort {
+        let mut waiting = self.waiting.lock().unwrap_or_else(|e| e.into_inner());
+        let count = waiting.len().min(crate::wal::MAX_GROUP_TRANSACTIONS);
+        Cohort(waiting.drain(..count).collect())
+    }
+    pub(crate) fn cancel(&self, pending: &Arc<Pending>) {
+        pending.cancelled.store(true, Ordering::Release);
+        pending.completed.store(true, Ordering::Release);
+        if let Some(publisher) = pending.publisher.lock().unwrap_or_else(|e| e.into_inner()).as_ref() { publisher.unpark(); }
+        pending.transaction.lock().unwrap_or_else(|e| e.into_inner()).take();
+        let mut waiting = self.waiting.lock().unwrap_or_else(|e| e.into_inner());
+        waiting.retain(|entry| !Arc::ptr_eq(entry, pending));
+        if let Some(next) = waiting.front() { next.thread.unpark(); }
+    }
+}
+
+/// A panic or any early return wakes every removed member immediately.
+pub(crate) struct Cohort(Vec<Arc<Pending>>);
+impl std::ops::Deref for Cohort {
+    type Target = Vec<Arc<Pending>>;
+    fn deref(&self) -> &Self::Target { &self.0 }
+}
+impl Drop for Cohort {
+    fn drop(&mut self) {
+        for job in &self.0 {
+            job.reply(Err(io::Error::other("publication cohort unwound before completion")));
+        }
+    }
+}
+
