+        let next = queue.enqueue(database.begin(7, 12).unwrap(), deadline, u64::MAX);
+        assert_eq!(database.snapshot_pin_metrics().unwrap().active_handles, 2);
+        queue.cancel(&first);
+        assert_eq!(database.snapshot_pin_metrics().unwrap().active_handles, 1);
+        let leadership = queue.try_lead(&next).unwrap();
+        let cohort = queue.take_batch();
