+        assert!(next.take_result().unwrap().is_err());
+        assert!(next.take_result().is_none());
+        drop(leadership);
+        queue.cancel(&next);
+        assert_eq!(database.snapshot_pin_metrics().unwrap().active_handles, 0);
+    }
+
+    #[test]
+    fn expired_member_never_takes_its_transaction() {
