+    #[test]
+    fn failed_or_torn_cohort_write_fences_engine_before_any_acknowledgement() {
+        for action in [FaultAction::ErrorBefore(io::ErrorKind::Other), FaultAction::ShortWrite(20)] {
+            let vfs = Arc::new(DeterministicVfs::new(None));
