+/// One caller publishes a bounded FIFO cohort; others retain prepared leases
+/// and wait without reacquiring authority. Every success waits on the final
+/// written generation witness after the authority mutex has been released.
+fn publish_prepared_command(
+    stores: &StorageV2Stores<'_>,
+    transaction: crate::authority::AuthorityTransaction,
+    remaining_millis: u64,
+    deadline_unix_ms: u64,
+    now_unix_ms: &mut impl FnMut() -> u64,
+    alive: &mut impl FnMut() -> bool,
+) -> io::Result<Option<crate::publication_batch::Published>> {
+    let deadline = Instant::now() + Duration::from_millis(remaining_millis);
+    let queue = &stores.authority_admission.publication_queue;
+    let pending = queue.enqueue(transaction, deadline, deadline_unix_ms);
+    let _waiting = crate::fsync_stats::StageTimer::new(crate::fsync_stats::STAGE_PUBLICATION_QUEUE_WAIT);
+    loop {
+        if let Some(result) = pending.take_result() { return Ok(Some(result)); }
+        if !alive() { queue.cancel(&pending); return Ok(None); }
+        if Instant::now() >= deadline {
+            queue.cancel(&pending);
+            return Ok(Some(Err(io::Error::new(io::ErrorKind::TimedOut, "publication deadline elapsed"))));
+        }
+        if pending.authorization_requested() {
+            if now_unix_ms() >= deadline_unix_ms {
+                queue.cancel(&pending);
+                return Ok(Some(Err(io::Error::new(io::ErrorKind::TimedOut, "publication approval deadline elapsed"))));
+            }
+            pending.authorize();
+        }
+        if let Some(_leadership) = queue.try_lead(&pending) {
+            let remaining = deadline.saturating_duration_since(Instant::now()).as_millis() as u64;
+            match acquire_authority_until(stores.authority, remaining, alive, &stores.authority_admission) {
+                Ok(AuthorityAcquisition::Acquired(mut authority)) => {
+                    if !alive() { queue.cancel(&pending); drop(authority); return Ok(None); }
+                    let batch = queue.take_batch();
+                    let _execute = crate::fsync_stats::StageTimer::new(crate::fsync_stats::STAGE_PUBLICATION_BATCH_EXECUTE);
+                    {
+                        let _approval = crate::fsync_stats::StageTimer::new(crate::fsync_stats::STAGE_PUBLICATION_AUTHORIZE_WAIT);
+                        for job in batch.iter() {
+                            job.request_authorization();
+                            if Arc::ptr_eq(job, &pending) { job.authorize(); }
+                        }
+                        for job in batch.iter() { job.wait_for_authorization(); }
+                    }
+                    let results = {
+                        let _cohort = (batch.len() > 1).then(crate::request_profile::CohortContext::new);
+                        let mut publish = |authority: &mut AuthorityDatabase| {
+                            batch.iter().map(|job| {
+                                job.take_transaction(now_unix_ms()).and_then(|transaction| {
+                                    match transaction {
+                                        Some(transaction) => authority.commit(transaction),
+                                        None => Err(io::Error::new(io::ErrorKind::Interrupted, "publication cancelled")),
+                                    }
+                                })
+                            }).collect::<Vec<_>>()
+                        };
+                        if batch.len() > 1 { authority.publication_batch(publish) }
+                        else { Ok(publish(&mut authority)) }
+                    };
+                    let witness = stores.wal_barrier.as_ref().map(|barrier| authority.wal_len().and_then(|len| barrier.witness(len))).transpose();
+                    drop(_execute);
+                    drop(authority);
+                    match (results, witness) {
+                        (Ok(results), Ok(witness)) => {
+                            crate::fsync_stats::note_publication_batch(batch.len());
+                            for (job, result) in batch.iter().zip(results) { job.reply(result.map(|commit| (commit, witness.clone()))); }
+                        },
+                        (Err(error), _) | (_, Err(error)) => {
+                            for job in batch.iter() { job.reply(Err(io::Error::new(error.kind(), error.to_string()))); }
+                        }
+                    }
+                },
+                Ok(AuthorityAcquisition::ConnectionClosed) => { queue.cancel(&pending); return Ok(None); },
+                Ok(AuthorityAcquisition::DeadlineElapsed) => {
+                    queue.cancel(&pending);
+                    return Ok(Some(Err(io::Error::new(io::ErrorKind::TimedOut, "publication deadline elapsed"))));
+                },
+                Err(error) => { queue.cancel(&pending); return Err(error); }
+            }
+            continue;
+        }
+        thread::park_timeout(deadline.saturating_duration_since(Instant::now()).min(Duration::from_millis(25)));
+    }
+}
