+        let barrier = crate::wal::WalBarrier::default();
+        authority.attach_wal_barrier(&barrier).unwrap();
+        let mut transactions = Vec::new();
+        for (owner, key, value) in [(11, b"same".as_slice(), b"first".as_slice()),
+            (12, b"independent".as_slice(), b"other owner".as_slice()),
+            (11, b"same".as_slice(), b"stale".as_slice())] {
+            let mut transaction = authority.begin(7, owner).unwrap();
+            authority.entity_put(&mut transaction, EntityKey::new(7, owner, "cohort-test", key).unwrap(), value.to_vec()).unwrap();
+            transactions.push(transaction);
+        }
+        let database = Mutex::new(authority);
+        let stores = StorageV2Stores::new(&database, None).with_wal_barrier(barrier.clone());
+        let guard = database.lock().unwrap();
+        let cancellation_allowed = Arc::new(std::sync::atomic::AtomicBool::new(false));
+        thread::scope(|scope| {
+            let mut handles = Vec::new();
+            for (index, transaction) in transactions.into_iter().enumerate() {
+                let stores = &stores;
+                let cancellation_allowed = Arc::clone(&cancellation_allowed);
+                handles.push(scope.spawn(move || {
+                    let mut checks = 0;
+                    publish_prepared_command(stores, transaction, 5_000, 10_000, &mut || 1_000, &mut || {
+                        checks += 1;
+                        !(cancel_second && index == 1 && checks >= 2 && cancellation_allowed.load(std::sync::atomic::Ordering::Acquire))
+                    }).unwrap()
+                }));
+                let deadline = Instant::now() + Duration::from_secs(2);
+                while stores.authority_admission.publication_queue.pending_count() != index + 1 {
+                    assert!(Instant::now() < deadline, "publisher did not enqueue");
+                    thread::yield_now();
+                }
+            }
+            cancellation_allowed.store(true, std::sync::atomic::Ordering::Release);
+            drop(guard);
+            let mut results = handles.into_iter().map(|h| h.join().unwrap());
+            let first = results.next().unwrap().unwrap().unwrap();
+            let next = results.next().unwrap();
+            let witness = if cancel_second {
+                assert!(next.is_none(), "disconnected peer published a transaction");
+                first.1.as_ref().unwrap().clone()
