+            let Err(error) = results.next().unwrap().unwrap() else { panic!("same-key stale commit accepted"); };
+            assert_eq!(error.kind(), io::ErrorKind::WouldBlock);
+            // A published response still cannot claim durability before fsync.
+            assert!(barrier.wait_witness(first.1.as_ref().unwrap(), Instant::now()).is_err());
+            barrier.sync_for_test(vfs.as_ref()).unwrap();
+            barrier.wait_witness(&witness, Instant::now()).unwrap();
+        });
+        let authority = database.lock().unwrap();
